/* Linker version script for libwbcrypto.so.
 *
 * Combined with -fvisibility=hidden, this exports ONLY the public C ABI
 * (wbc_*). Every C++ internal symbol (wbaes::*, vm::*, storage::*) and the
 * vendored libsodium symbols stay local, so the shipped .so's dynamic symbol
 * table does not hand an attacker a labelled map of the internals.
 */
{
  global:
    wbc_*;
  local:
    *;
};
